package agentpool_test

import (
	"context"
	"log/slog"
	"os"
	"path/filepath"
	"strings"

	"github.com/mudler/LocalAI/core/config"
	"github.com/mudler/LocalAI/core/services/agentpool"
	"github.com/mudler/xlog"
	. "github.com/onsi/ginkgo/v2"
	. "github.com/onsi/gomega"
)

var _ = Describe("legacy auth warning", func() {
	const warning = "User authentication is enabled but root agent data has no owner"
	var dir string
	var logFile *os.File

	BeforeEach(func() {
		dir = GinkgoT().TempDir()
		var err error
		logFile, err = os.CreateTemp(dir, "startup-*.log")
		Expect(err).NotTo(HaveOccurred())
		xlog.SetLogger(xlog.NewLoggerWithHandler(slog.NewTextHandler(logFile, nil), xlog.LogLevelInfo))
	})
	AfterEach(func() {
		xlog.SetLogger(xlog.NewLogger(xlog.LogLevelInfo, "text"))
		Expect(logFile.Close()).To(Succeed())
	})

	write := func(path, data string) {
		Expect(os.MkdirAll(filepath.Dir(path), 0750)).To(Succeed())
		Expect(os.WriteFile(path, []byte(data), 0600)).To(Succeed())
	}
	start := func(enabled bool, collectionPath string) string {
		cfg := config.NewApplicationConfig()
		cfg.Auth.Enabled = enabled
		cfg.AgentPool = config.AgentPoolConfig{
			Enabled: true, StateDir: dir, APIURL: "http://127.0.0.1:1",
			DefaultModel: "unused", CollectionDBPath: collectionPath,
		}
		svc, err := agentpool.NewAgentPoolService(cfg)
		Expect(err).NotTo(HaveOccurred())
		Expect(svc.Start(context.Background())).To(Succeed())
		svc.Stop()
		data, err := os.ReadFile(logFile.Name())
		Expect(err).NotTo(HaveOccurred())
		return string(data)
	}

	It("warns about root agents, custom-path collections, skills and git repositories", func() {
		write(filepath.Join(dir, "pool.json"), `{"legacy":{"name":"legacy","model":"unused"},"owner:private":{"name":"owner:private","model":"unused"}}`)
		collectionsDir := filepath.Join(GinkgoT().TempDir(), "collections")
		write(filepath.Join(collectionsDir, "collection-notes.json"), `{}`)
		write(filepath.Join(dir, "skills", "legacy-skill", "SKILL.md"), "---\nname: legacy-skill\ndescription: A legacy skill\n---\nInstructions\n")
		write(filepath.Join(dir, "skills", ".git-repos.json"), `[{"id":"old","name":"old","url":"https://example.invalid/old.git","enabled":false}]`)
		logs := start(true, collectionsDir)
		Expect(logs).To(ContainSubstring(warning))
		Expect(logs).To(ContainSubstring("agents=1 collections=1 skills=1 git_repositories=1"))
		Expect(logs).To(ContainSubstring("authentication/#enabling-auth-on-an-existing-instance"))
		Expect(logs).NotTo(ContainSubstring("agents=2"))
		Expect(strings.Index(logs, warning)).To(BeNumerically("<", strings.Index(logs, "Creating agent")))
	})

	It("does not warn when auth is disabled", func() {
		write(filepath.Join(dir, "skills", "legacy-skill", "SKILL.md"), "---\nname: legacy-skill\ndescription: A legacy skill\n---\nInstructions\n")
		Expect(start(false, "")).NotTo(ContainSubstring(warning))
	})

	It("does not count user-owned data as root data", func() {
		write(filepath.Join(dir, "pool.json"), `{"owner:private":{"name":"owner:private","model":"unused"}}`)
		write(filepath.Join(dir, "users", "owner", "collections", "collection-notes.json"), `{}`)
		write(filepath.Join(dir, "users", "owner", "skills", "private", "SKILL.md"), "---\nname: private\ndescription: Private skill\n---\nInstructions\n")
		Expect(start(true, "")).NotTo(ContainSubstring(warning))
	})

	It("warns for configured git repositories even without installed skills", func() {
		write(filepath.Join(dir, "skills", ".git-repos.json"), `[{"id":"old","name":"old","url":"https://example.invalid/old.git","enabled":false}]`)
		logs := start(true, "")
		Expect(logs).To(ContainSubstring(warning))
		Expect(logs).To(ContainSubstring("agents=0 collections=0 skills=0 git_repositories=1"))
	})

	It("reports an unreadable repository config without preventing startup", func() {
		write(filepath.Join(dir, "collections", "collection-notes.json"), `{}`)
		write(filepath.Join(dir, "skills", ".git-repos.json"), `invalid json`)
		logs := start(true, "")
		Expect(logs).To(ContainSubstring("Could not check root skill repositories"))
		Expect(logs).To(ContainSubstring(warning))
		Expect(logs).To(ContainSubstring("agents=0 collections=1"))
	})
})

package agents

import (
	"context"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"sort"
	"sync"
	"sync/atomic"

	"github.com/modelcontextprotocol/go-sdk/mcp"
	"github.com/mudler/LocalAGI/core/state"
	"github.com/mudler/cogito"
	openai "github.com/sashabaranov/go-openai"

	. "github.com/onsi/ginkgo/v2"
	. "github.com/onsi/gomega"
)

// mcpFixture serves an MCP server over SSE whose tools return fixed results,
// so the executor reaches it through the same transport as a real agent.
type mcpFixture struct {
	server *httptest.Server
	calls  map[string]*atomic.Int32
}

func newMCPFixture(results map[string]string) *mcpFixture {
	srv := mcp.NewServer(&mcp.Implementation{Name: "fixture", Version: "v0.0.1"}, nil)
	fx := &mcpFixture{calls: map[string]*atomic.Int32{}}
	for name, result := range results {
		counter := &atomic.Int32{}
		fx.calls[name] = counter
		srv.AddTool(&mcp.Tool{
			Name:        name,
			Description: "fixture tool " + name,
			InputSchema: json.RawMessage(`{"type":"object","properties":{}}`),
		}, func(context.Context, *mcp.CallToolRequest) (*mcp.CallToolResult, error) {
			counter.Add(1)
			return &mcp.CallToolResult{Content: []mcp.Content{&mcp.TextContent{Text: result}}}, nil
		})
	}
	fx.server = httptest.NewServer(mcp.NewSSEHandler(func(*http.Request) *mcp.Server { return srv }, nil))
	return fx
}

func (fx *mcpFixture) close()                   { fx.server.Close() }
func (fx *mcpFixture) callCount(n string) int32 { return fx.calls[n].Load() }

// policyLLM answers each chat completion through respond (plain text answer
// when respond is nil) and records every
// request, so specs can see which tools were offered and which messages the
// executor added.
type policyLLM struct {
	mu       sync.Mutex
	requests []openai.ChatCompletionRequest
	asked    [][]openai.ChatCompletionMessage
	respond  func(req openai.ChatCompletionRequest) openai.ChatCompletionMessage
	answer   string
}

func (m *policyLLM) Ask(_ context.Context, f cogito.Fragment) (cogito.Fragment, error) {
	m.mu.Lock()
	m.asked = append(m.asked, append([]openai.ChatCompletionMessage(nil), f.Messages...))
	m.mu.Unlock()
	return f.AddMessage(cogito.AssistantMessageRole, m.answer), nil
}

func (m *policyLLM) CreateChatCompletion(_ context.Context, req openai.ChatCompletionRequest) (cogito.LLMReply, cogito.LLMUsage, error) {
	m.mu.Lock()
	m.requests = append(m.requests, req)
	m.mu.Unlock()
	msg := openai.ChatCompletionMessage{Role: "assistant", Content: m.answer}
	if m.respond != nil {
		msg = m.respond(req)
	}
	return cogito.LLMReply{
		ChatCompletionResponse: openai.ChatCompletionResponse{
			Choices: []openai.ChatCompletionChoice{{Message: msg}},
		},
	}, cogito.LLMUsage{}, nil
}

// offeredTools returns the sorted tool names of the first request that
// offered tools to the model.
func (m *policyLLM) offeredTools() []string {
	m.mu.Lock()
	defer m.mu.Unlock()
	for _, req := range m.requests {
		if len(req.Tools) == 0 {
			continue
		}
		names := []string{}
		for _, t := range req.Tools {
			if t.Function != nil {
				names = append(names, t.Function.Name)
			}
		}
		sort.Strings(names)
		return names
	}
	return nil
}

// nudges counts the user messages carrying prompt in the longest conversation
// the model saw, which is the number of times the gate sent it.
func (m *policyLLM) nudges(prompt string) int {
	m.mu.Lock()
	defer m.mu.Unlock()
	best := 0
	count := func(msgs []openai.ChatCompletionMessage) {
		n := 0
		for _, msg := range msgs {
			if msg.Role == "user" && msg.Content == prompt {
				n++
			}
		}
		if n > best {
			best = n
		}
	}
	for _, req := range m.requests {
		count(req.Messages)
	}
	for _, msgs := range m.asked {
		count(msgs)
	}
	return best
}

func toolCallMessage(name string) openai.ChatCompletionMessage {
	return openai.ChatCompletionMessage{
		Role: "assistant",
		ToolCalls: []openai.ToolCall{{
			ID:       "call-" + name,
			Type:     openai.ToolTypeFunction,
			Function: openai.FunctionCall{Name: name, Arguments: `{}`},
		}},
	}
}

func lastMessage(req openai.ChatCompletionRequest) openai.ChatCompletionMessage {
	if len(req.Messages) == 0 {
		return openai.ChatCompletionMessage{}
	}
	return req.Messages[len(req.Messages)-1]
}

var _ = Describe("tool policy settings", func() {
	Describe("config parsing", func() {
		It("accepts the tool lists as a comma or newline separated string", func() {
			var cfg AgentConfig
			Expect(ParseConfigJSON(`{"allowed_tools":"a, b\nc,,","excluded_tools":" d \r\n"}`, &cfg)).To(Succeed())
			Expect([]string(cfg.AllowedTools)).To(Equal([]string{"a", "b", "c"}))
			Expect([]string(cfg.ExcludedTools)).To(Equal([]string{"d"}))
		})

		It("accepts the tool lists as a JSON array", func() {
			var cfg AgentConfig
			Expect(ParseConfigJSON(`{"allowed_tools":["a"," b ",""],"excluded_tools":null}`, &cfg)).To(Succeed())
			Expect([]string(cfg.AllowedTools)).To(Equal([]string{"a", "b"}))
			Expect(cfg.ExcludedTools).To(BeEmpty())
		})

		It("rejects a list with non-string entries", func() {
			var cfg AgentConfig
			Expect(ParseConfigJSON(`{"allowed_tools":[1]}`, &cfg)).ToNot(Succeed())
		})

		It("keeps every setting when the config is stored through LocalAGI's config", func() {
			// The REST handlers decode into state.AgentConfig and store its JSON;
			// the distributed dispatcher decodes that JSON into AgentConfig.
			var in state.AgentConfig
			Expect(json.Unmarshal([]byte(`{
				"name": "a",
				"allowed_tools": "search, check_policy",
				"excluded_tools": ["add_memory"],
				"required_tool_before_finish": "check_policy",
				"required_tool_before_finish_prompt": "run it",
