		It("skips agents that are not due yet", func() {
			recent := time.Now().Add(-2 * time.Minute)
			cfg := AgentConfig{
				StandaloneJob: true,
				PeriodicRuns:  "10m",
			}
			cfgJSON, _ := json.Marshal(cfg)

			mStore.configs = []AgentConfigRecord{
				{
					ID:         "rec-2",
					UserID:     "user-1",
					Name:       "not-yet-agent",
					ConfigJSON: string(cfgJSON),
					Status:     StatusActive,
					LastRunAt:  &recent,
				},
			}

			sched.runDueAgents(context.Background())

			Expect(queue.calls).To(BeEmpty())
		})

		It("skips non-standalone agents", func() {
			past := time.Now().Add(-15 * time.Minute)
			cfg := AgentConfig{
				StandaloneJob: false,
				PeriodicRuns:  "10m",
			}
			cfgJSON, _ := json.Marshal(cfg)

			mStore.configs = []AgentConfigRecord{
				{
					ID:         "rec-3",
					UserID:     "user-1",
					Name:       "interactive-agent",
					ConfigJSON: string(cfgJSON),
					Status:     StatusActive,
					LastRunAt:  &past,
				},
			}

			sched.runDueAgents(context.Background())

			Expect(queue.calls).To(BeEmpty())
		})

		It("skips paused agents", func() {
			past := time.Now().Add(-15 * time.Minute)
			cfg := AgentConfig{
				StandaloneJob: true,
				PeriodicRuns:  "10m",
			}
			cfgJSON, _ := json.Marshal(cfg)

			mStore.configs = []AgentConfigRecord{
				{
					ID:         "rec-4",
					UserID:     "user-1",
					Name:       "paused-agent",
					ConfigJSON: string(cfgJSON),
					Status:     StatusPaused,
					LastRunAt:  &past,
				},
			}

			sched.runDueAgents(context.Background())

			Expect(queue.calls).To(BeEmpty())
		})

		It("skips agents with invalid config JSON", func() {
			past := time.Now().Add(-15 * time.Minute)

			mStore.configs = []AgentConfigRecord{
				{
					ID:         "rec-5",
					UserID:     "user-1",
					Name:       "broken-agent",
					ConfigJSON: `{invalid json`,
					Status:     StatusActive,
					LastRunAt:  &past,
				},
			}

			sched.runDueAgents(context.Background())

			Expect(queue.calls).To(BeEmpty())
		})

		It("updates last run timestamp after enqueueing", func() {
			cfg := AgentConfig{
				StandaloneJob: true,
				PeriodicRuns:  "10m",
			}
			cfgJSON, _ := json.Marshal(cfg)

			mStore.configs = []AgentConfigRecord{
				{
					ID:         "rec-6",
					UserID:     "user-1",
					Name:       "track-agent",
					ConfigJSON: string(cfgJSON),
					Status:     StatusActive,
					LastRunAt:  nil, // never run — due immediately
				},
			}

			sched.runDueAgents(context.Background())

			Expect(queue.calls).To(HaveLen(1))
			Expect(mStore.updated).To(HaveLen(1))
			Expect(mStore.updated[0].userID).To(Equal("user-1"))
			Expect(mStore.updated[0].name).To(Equal("track-agent"))
		})

		It("enriches event with skills when skill provider is set", func() {
			cfg := AgentConfig{
				StandaloneJob: true,
				PeriodicRuns:  "10m",
				EnableSkills:  true,
			}
			cfgJSON, _ := json.Marshal(cfg)

			mStore.configs = []AgentConfigRecord{
				{
					ID:         "rec-7",
					UserID:     "user-1",
					Name:       "skilled-agent",
					ConfigJSON: string(cfgJSON),
					Status:     StatusActive,
					LastRunAt:  nil,
				},
			}

			skills := []SkillInfo{
				{Name: "search", Description: "Search the web"},
				{Name: "code", Description: "Write code"},
			}
			provider := func(userID string) ([]SkillInfo, error) {
				return skills, nil
			}
			sched.skillProvider = provider

			sched.runDueAgents(context.Background())

			Expect(queue.calls).To(HaveLen(1))
			evt, ok := queue.calls[0].payload.(AgentChatEvent)
			Expect(ok).To(BeTrue())
			Expect(evt.Skills).To(HaveLen(2))
			Expect(evt.Skills[0].Name).To(Equal("search"))
			Expect(evt.Skills[1].Name).To(Equal("code"))
		})

		It("handles multiple agents in a single run", func() {
			past := time.Now().Add(-15 * time.Minute)
			cfg := AgentConfig{
				StandaloneJob: true,
				PeriodicRuns:  "10m",
			}
			cfgJSON, _ := json.Marshal(cfg)

			mStore.configs = []AgentConfigRecord{
				{
					ID:         "rec-a",
					UserID:     "user-1",
					Name:       "agent-a",
					ConfigJSON: string(cfgJSON),
					Status:     StatusActive,
					LastRunAt:  &past,
				},
				{
					ID:         "rec-b",
					UserID:     "user-2",
					Name:       "agent-b",
					ConfigJSON: string(cfgJSON),
					Status:     StatusActive,
					LastRunAt:  nil, // never run
				},
			}

			sched.runDueAgents(context.Background())

			Expect(queue.calls).To(HaveLen(2))
			names := []string{
				queue.calls[0].payload.(AgentChatEvent).AgentName,
				queue.calls[1].payload.(AgentChatEvent).AgentName,
			}
			Expect(names).To(ConsistOf("agent-a", "agent-b"))
		})

		It("uses default interval when PeriodicRuns is empty", func() {
			// Default is 10m; set last run to 11 minutes ago => should be due
			past := time.Now().Add(-11 * time.Minute)
			cfg := AgentConfig{
				StandaloneJob: true,
				PeriodicRuns:  "", // empty => 10m default
			}
			cfgJSON, _ := json.Marshal(cfg)

			mStore.configs = []AgentConfigRecord{
				{
					ID:         "rec-8",
					UserID:     "user-1",
					Name:       "default-interval-agent",
					ConfigJSON: string(cfgJSON),
					Status:     StatusActive,
					LastRunAt:  &past,
				},
			}

			sched.runDueAgents(context.Background())

			Expect(queue.calls).To(HaveLen(1))
		})
	})
})

